mapper.update:
-- 注意：Mybatis默认只能执行一条sql，多条sql需要配置allowMultiQueries=true -- 1.快照表插入新数据,让id连续的写法 insert into ebook_snapshot(ebook_id, date, view_count, vote_count, view_increase, vote_increase) select t1.id, curdate(), 0, 0, 0, 0 from ebook t1 where not exists(select 1 from ebook_snapshot t2 where t1.id = t2.ebook_id and t2.date = curdate());
-- 2.更新快照表 update ebook_snapshot t1,ebook t2 set t1.view_count = t2.view_count, t1.vote_count=t2.vote_count where t1.date = curdate() and t1.ebook_id = t2.id;
-- 3.获取昨天的数据 update ebook_snapshot t1 left join (select ebook_id, view_count, vote_count from ebook_snapshot where date = date_sub(CURDATE(), interval 1 day)) t2 on t1.ebook_id = t2.ebook_id set t1.view_increase = (t1.view_count - IFNULL(t2.view_count, 0)), t1.vote_increase = (t1.vote_count - IFNULL(t2.vote_count, 0)) where t1.date = curdate();
